      "quote": "Drug treatments for covid-19: living systematic review and network meta-analysis",
      "reason": "The title explicitly identifies the report as a (living) systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Drug treatments for covid-19: living systematic review and network meta-analysis",
      "reason": "The title conveys the intervention (drug treatments) and the population/condition (covid-19), reflecting the main objective of comparing effects of drug treatments for covid-19 as stated in the introduction."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Drug treatments for covid-19: living systematic review and network meta-analysis",
