{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "As of 23 March 2022, more than 475 million people have been infected with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2)... Despite global efforts to identify effective interventions for the prevention and treatment of covid-19, which have resulted in approximately 3000 trials completed or underway, evidence for effective treatment remains limited.",
      "reason": "The introduction describes the current state of knowledge (large trial volume) and the key uncertainty (limited evidence for effective treatment) with citations."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Summarising the rapidly growing evidence base has been a challenge. Living systematic reviews deal with the main limitation of traditional reviews-that of providing an overview of the relevant evidence only at a specific time. This is crucial in the context of covid-19, in which the best evidence is constantly changing.",
      "reason": "The need and importance of the review are explicitly explained in the context of a rapidly evolving evidence base and changing best evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "This living network meta-analysis is the fifth version. The previous versions are available in the supplementary material. Drugs for prophylaxis 9 and antibody-based treatments 10 are addressed separately.",
      "reason": "As an update, the manuscript identifies this as the fifth version with previous versions cited, and the discussion (callout_2) also distinguishes it from two other similar efforts, explaining the need for this review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PARTIAL",
      "chunk_id": "callout_2",
      "quote": "Mounting evidence suggests that antivirals (such as molnupiravir and nirmatrelvir) are most effective in the early stages of covid-19 when patients have non-severe disease, whereas anti-inflammatories (such as corticosteroids) seem to be most effective in the later disease stages.",
      "reason": "A brief mechanistic rationale (antivirals early vs anti-inflammatories late in disease) appears only in the strengths/limitations section as a future-direction justification, not in the introduction where the rationale for the interventions is described; hence partial."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of drug treatments (pharmacological interventions) for covid-19, not a complex intervention or complex delivery context, so a logic model is not required."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "To compare the effects of treatments for coronavirus disease 2019 (covid-19).",
      "reason": "The abstract contains an explicit objective statement clearly declaring the review's aim."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Randomised clinical trials in which people with suspected, probable, or confirmed covid-19 were randomised to drug treatment or to standard care or placebo.",
      "reason": "Population (people with covid-19), interventions (drug treatments), and comparators (standard care or placebo) are identifiable, but the planned comparisons are not explicitly stated in PICO form alongside the objective; outcomes are described separately in the Data Collection section."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "We included randomised clinical trials in people with suspected, probable, or confirmed covid-19 that compared drugs for treatment against one another or against no intervention, placebo, or standard care... No restrictions were applied based on severity of illness or setting",
      "reason": "Eligibility criteria specify population (covid-19 patients), design (randomised trials), comparisons, and state no restrictions on setting or severity; follow-up not restricted."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language.",
      "reason": "Explicitly states no restrictions on publication status or language; no year restrictions implied by comprehensive search."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_26",
      "quote": "Several trials could not be included in the analysis because both arms would have been classified within the same treatment node, they evaluated different durations or doses of the same drug, had insufficient data, or reported no outcomes of interest.",
      "reason": "Distinguishes reasons for exclusion; 'had insufficient data' vs 'reported no outcomes of interest' and figure 1 excludes 'Randomised trial with no results', distinguishing measured vs reported outcomes, though not fully explicit."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "For each outcome, interventions were classified in groups from the most to the least beneficial or harmful following GRADE guidance.",
      "reason": "Grouping into nodes/classes is implied via treatment nodes and the at-least-100-patients/20-events analysis threshold, and interventions excluded are categorised separately (text_13), but the full list of synthesis groups/comparisons defined in the objectives is not explicitly specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "we decided to report evidence on treatments for which at least 100 people were randomised or for which there were at least 20 events... We include preprints because of the urgent need for information and because so many of the studies on covid-19 are published first as preprints.",
      "reason": "Rationales are given for notable restrictions (analysis threshold for sparse data; inclusion of preprints; grouping placebo/standard care in same node)."
    }
  ],
  "confidence": 82
}

