    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "We used a hierarchy for the outcome mechanical ventilation in which we preferentially used the total number of patients who received mechanical ventilation over the study. ... Weused author definitions for mechanical ventilation; when separate, continuous positive airway pressure (CPAP) and bilevel positive airway pressure (BiPAP) were considered non-invasive mechanical ventilation.",
      "reason": "The authors describe assumptions/decisions for handling unclear or inconsistently reported information (a hierarchy for mechanical ventilation, use of author definitions, counting CPAP/BiPAP as non-invasive ventilation, and updating preprint data when peer-reviewed versions appeared)."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Outcomesofinterestwereselectedbasedonimportancetopatients 18 and were informed by clinical expertise in the systematic review teamandinthelinkedguidelinepanelresponsiblefortheWHOBMJ Rapid Recommendations.",
      "reason": "A cited source (reference 18, a patient-important outcomes study) and the WHO/BMJ Rapid Recommendations panel rating process (outcomes rated 7 or higher) were used to determine which data items (outcomes) to collect."
    }
  ],
  "confidence": 85
